from pathlib import Path
import json
P=Path('character/crew-side-gameplay-review-v1');P.mkdir(exist_ok=True);tracks=[]
choices=[('Bill east','bill','east','bill-idle-led-east-neutral-v1'),('Bill west','bill','west','bill-idle-led-west-matched-v1'),('James east','branforth','east','branforth-idle-led-east-neutral-v3'),('James west — provisional','branforth','west','branforth-idle-led-west-timing-v1')]
for label,who,d,folder in choices:
 r=Path('character')/folder;m=json.loads((r/'manifest.json').read_text());s=m['states'][0];ir=Path('character/crew-idle-match-v1')/who;im=json.loads((ir/'manifest.json').read_text());idle=next(s for s in im['states'] if s['id']=='idle-'+d);tracks.append({'label':label,'files':['../'+folder+'/'+f for f in s['frameFiles']],'durations':s['frameDurationsMs'],'idle':'../crew-idle-match-v1/'+who+'/'+idle['frameFiles'][0]})
html='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crew side walks at gameplay sizes</title><style>body{background:#172226;color:#dbe4df;font:17px system-ui;margin:24px}button,select{font:inherit;padding:8px}canvas{display:block;width:980px;height:620px}.board{overflow:auto;max-width:100%}</style><h1>Side walks at gameplay sizes</h1><p>82px,54px and27px standing heights. Browser scale review—not an engine test. James west remains provisional.</p><button id="play">Pause</button> <select id="mode"><option value="walk">Continuous walk</option><option value="transition">Idle / walk transition</option></select><p id="status">Loading…</p><div class="board"><canvas id="board" width="980" height="620"></canvas></div><p>Exact selected PNGs and manifest timing, linear sampling. No generation or runtime installation.</p><script>const tracks=TRACKS;const c=document.querySelector('canvas'),ctx=c.getContext('2d');let t=0,last=0,playing=true,ready=false;function load(src){return new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(Error(src));im.src=src})}Promise.all(tracks.map(async s=>{s.images=await Promise.all(s.files.map(load));s.idleImage=await load(s.idle);s.total=s.durations.reduce((a,b)=>a+b,0)})).then(()=>{ready=true;document.querySelector('#status').textContent='All selected frames loaded'}).catch(()=>document.querySelector('#status').textContent='An image failed to load; reload to retry.');document.querySelector('#play').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};function draw(now){if(last&&playing)t+=now-last;last=now;if(ready){ctx.fillStyle='#303b40';ctx.fillRect(0,0,980,620);ctx.imageSmoothingEnabled=true;ctx.fillStyle='#dbe4df';ctx.font='17px system-ui';[82,54,27].forEach((h,j)=>ctx.fillText(h+'px',330+j*220,25));tracks.forEach((s,row)=>{const base=150+row*150;let q=t%s.total,i=0;while(i<s.images.length-1&&q>=s.durations[i])q-=s.durations[i++];const idle=document.querySelector('#mode').value==='transition'&&Math.floor(t/2200)%2===0;ctx.fillStyle='#dbe4df';ctx.fillText(s.label,15,base-75);ctx.font='13px system-ui';ctx.fillText(idle?'Idle':('Frame '+(i+1)+' / '+s.images.length),15,base-50);ctx.font='17px system-ui';[82,54,27].forEach((h,j)=>{const z=h/148,x=350+j*220;ctx.strokeStyle='#62757a';ctx.beginPath();ctx.moveTo(x-80,base);ctx.lineTo(x+80,base);ctx.stroke();ctx.drawImage(idle?s.idleImage:s.images[i],x-92*z,base-172*z,184*z,184*z)})})}requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>''';(P/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)),encoding='utf-8');(P/'selection.json').write_text(json.dumps(choices,indent=2));print('4 clips;184 selected walking frames; all manifest references exist:',all((P/f).exists() for s in tracks for f in s['files']+[s['idle']]))
